    const pems = selfsigned.generate([{ name: "commonName", value: "localhost" }], { days: CERTIFICATE_DAYS, keySize: 2048, extensions: [{ name: "subjectAltName", altNames: [{ type: 2, value: "localhost" }, { type: 7, ip: "127.0.0.1" }] }] });
